SELECT *, ROW_NUMBER() OVER w_running AS seq_no, NTILE(5) OVER w_grp AS temp_c_bucket, NTILE(4) OVER w_part AS status_bits_bucket, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_bits, MIN(status_bits) OVER (PARTITION BY device_code) AS device_code_min_status_bits FROM device_readings WINDOW w_running AS (PARTITION BY device_code ORDER BY temp_c DESC, id), w_grp AS (ORDER BY temp_c, id), w_part AS (PARTITION BY device_code ORDER BY status_bits DESC, id);
